<script>
(() => {
  'use strict';
  const NS = 'http://www.w3.org/2000/svg';
  const make = (tag, attrs, parent) => {
    const node = document.createElementNS(NS, tag);
    for (const [key, value] of Object.entries(attrs)) node.setAttribute(key, value);
    if (parent) parent.appendChild(node);
    return node;
  };

  // Deterministic hand-drawn fleece details.
  let seed = 47;
  const random = () => {
    seed = (seed * 16807) % 2147483647;
    return (seed - 1) / 2147483646;
  };
  const texture = document.getElementById('fleece-texture');
  for (let i = 0; i < 155; i++) {
    const x = 478 + random() * 263;
    const y = 239 + random() * 222;
    const torso = ((x - 603) / 125) ** 2 + ((y - 396) / 66) ** 2 < .91;
    const neck = x > 694 && x < 729 && y > 252 && y < 390;
    if (!torso && !neck) continue;
    const r = 3 + random() * 4;
    make('path', {
      d: `M ${x-r} ${y} q ${r*.2} ${-r} ${r} ${-r*.65} q ${r*.9} ${-r*.4} ${r*1.3} ${r*.55}`,
      fill: 'none',
      stroke: i % 3 ? '#fffaf0' : '#c9b18d',
      'stroke-opacity': i % 3 ? .63 : .24,
      'stroke-width': i % 3 ? 2.1 : 1.15,
      'stroke-linecap': 'round'
    }, texture);
  }

  const ground = document.getElementById('ground-details');
  const marks = [];
  for (let i = 0; i < 44; i++) {
    const x = random() * 1440;
    const y = 569 + random() * 63;
    const width = 2 + random() * 8;
    const node = make('path', {
      d: `M 0 0 q ${width*.5} -1 ${width} 0`,
      fill: 'none', stroke: i % 4 ? '#bfae88' : '#fff5df',
      'stroke-width': i % 4 ? 1.3 : 2,
      'stroke-linecap': 'round', opacity: .35
    }, ground);
    marks.push({node, x, y});
  }

  const legs = [
    {x: 525, y: 423, phase: .50, front: false, far: true},
    {x: 696, y: 414, phase: .75, front: true,  far: true},
    {x: 516, y: 425, phase: .00, front: false, far: false},
    {x: 685, y: 417, phase: .25, front: true,  far: false}
  ].map(spec => {
    const group = make('g', {}, document.getElementById(spec.far ? 'far-legs' : 'near-legs'));
    const shape = make('path', {
      fill: spec.far ? 'url(#far-leg)' : 'url(#near-leg)',
      stroke: spec.far ? '#c0a888' : '#d5be9b',
      'stroke-width': 1, 'stroke-linejoin': 'round'
    }, group);
    const highlight = make('path', {
      fill: 'none', stroke: '#fff5df',
      'stroke-width': 2.5, opacity: spec.far ? .15 : .55,
      'stroke-linecap': 'round'
    }, group);
    const hoof = make('path', {fill: spec.far ? '#85745c' : '#746451'}, group);
    const seam = make('path', {
      fill: 'none', stroke: '#514c40', 'stroke-width': 1, opacity: .5
    }, group);
    return {...spec, shape, highlight, hoof, seam};
  });

  const body = document.getElementById('alpaca-body');
  const head = document.getElementById('head');
  const tail = document.getElementById('tail');
  const shadow = document.getElementById('contact-shadow');
  const TAU = Math.PI * 2;
  const duration = 2.65;
  const stance = .66;
  const stride = 65;
  const groundSpeed = stride / (duration * stance);
  let start;

  function draw(now) {
    if (start === undefined) start = now;
    const t = (now - start) / 1000;
    const cycle = t / duration;
    const bob = Math.cos(cycle * TAU * 2) * 1.7;
    const sway = Math.sin(cycle * TAU) * 1.15;
    const pitch = Math.sin(cycle * TAU) * .32;
    body.setAttribute('transform', `translate(${sway} ${bob}) rotate(${pitch} 609 392)`);
    head.setAttribute('transform', `rotate(${Math.sin(cycle * TAU - .5) * .85} 714 272)`);
    tail.setAttribute('transform', `rotate(${Math.sin(cycle * TAU + 1) * 3} 491 357)`);
    shadow.setAttribute('rx', 157 + bob * 1.2);

    for (const leg of legs) {
      const phase = (cycle + leg.phase) % 1;
      const hx = leg.x + sway;
      const hy = leg.y + bob + (leg.x - 609) * Math.sin(pitch * Math.PI / 180);
      let fx, lift, toeAngle;
      if (phase < stance) {
        const u = phase / stance;
        fx = leg.x + stride * (.5 - u);
        lift = 0;
        toeAngle = 0;
      } else {
        const u = (phase - stance) / (1 - stance);
        // Matching touchdown and liftoff velocity avoids a sliding, pendulum gait.
        const ratio = (1 - stance) / stance;
        const travel = -2*u*u*u + 3*u*u - ratio*(2*u*u*u - 3*u*u + u);
        fx = leg.x + stride * (travel - .5);
        lift = 25 * Math.pow(Math.sin(Math.PI * u), 1.35);
        toeAngle = Math.sin(TAU * u) * 13;
      }
      const fy = 550 - lift + (leg.far ? -3 : 0);
      const dx = fx - hx, dy = fy - hy;
      const distance = Math.hypot(dx, dy);
      const upper = 76, lower = 76;
      const along = (upper*upper - lower*lower + distance*distance) / (2*distance);
      const bend = Math.sqrt(Math.max(0, upper*upper - along*along));
      const direction = leg.front ? -1 : 1;
      const kx = hx + dx * along / distance + direction * (-dy / distance) * bend;
      const ky = hy + dy * along / distance + direction * ( dx / distance) * bend;

      const w = leg.far ? 12 : 14;
      leg.shape.setAttribute('d', `
        M ${hx-w} ${hy-10}
        Q ${hx-15} ${hy+17} ${kx-8} ${ky}
        Q ${kx-6} ${ky+12} ${fx-5.5} ${fy+1}
        Q ${fx} ${fy+5} ${fx+6} ${fy+1}
        Q ${fx+7} ${fy-16} ${kx+8} ${ky+1}
        Q ${hx+15} ${hy+15} ${hx+w} ${hy-8}
        Q ${hx+6} ${hy-15} ${hx+1} ${hy-9}
        Q ${hx-5} ${hy-16} ${hx-w} ${hy-10} Z`);
      leg.highlight.setAttribute('d', `M ${hx-5} ${hy+5} Q ${hx-6} ${hy+23} ${kx-2} ${ky-1} Q ${kx+1} ${ky+13} ${fx-1} ${fy-10}`);

      const hoofPath = `M ${fx-6} ${fy-3}
        Q ${fx} ${fy-1} ${fx+6} ${fy-3}
        L ${fx+10} ${fy+3}
        Q ${fx+11} ${fy+7} ${fx+7} ${fy+7}
        L ${fx-5} ${fy+7}
        Q ${fx-8} ${fy+6} ${fx-6} ${fy-3} Z`;
      leg.hoof.setAttribute('d', hoofPath);
      leg.hoof.setAttribute('transform', `rotate(${toeAngle} ${fx} ${fy})`);
      leg.seam.setAttribute('d', `M ${fx+3} ${fy+3} l 1 4`);
      leg.seam.setAttribute('transform', `rotate(${toeAngle} ${fx} ${fy})`);
    }

    for (const mark of marks) {
      const x = ((mark.x - t * groundSpeed) % 1440 + 1440) % 1440 - 80;
      mark.node.setAttribute('transform', `translate(${x} ${mark.y})`);
    }
    requestAnimationFrame(draw);
  }
  requestAnimationFrame(draw);
})();
</script>
